const end = toIsoTimestamp(\"2030-01-03T00:00:00Z\");
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
afterEach(() => vi.useRealTimers());

function absence(tenant: Tenant) {
  return { orgId: tenant.org.id, userId: tenant.userIds.member,
    delegateUserId: tenant.userIds.viewer, startsAt: start, endsAt: end, note: \"On leave\" };
}
function at(instant: string) {
  vi.useFakeTimers({ toFake: [\"Date\"] });
  vi.setSystemTime(new Date(instant));
}
async function alerts(tenant: Tenant, role: \"member\" | \"viewer\", kind: \"issue_assigned\" | \"issue_overdue\" | \"comment_mention\") {
  return (await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id, recipientId: tenant.userIds[role], kind: [kind],
    unreadOnly: false, limit: 100, cursor: null,
  })).items;
}

describe(\"member absences\", () => {
  it(\"persists, replaces, returns scheduled absences, and expires at the exclusive end\", async () => {
    const tenant = await createTenant(\"absence-storage\");
    at(\"2030-01-01T00:00:00Z\");
    const input = absence(tenant);
    expect(await memberService.setAbsence(tenant.actors.member, input)).toEqual(input);
    expect(await memberService.getAbsence(tenant.actors.viewer, input.orgId, input.userId)).toEqual(input);
    const replacement = { ...input, note: null, delegateUserId: null };
    expect(await memberService.setAbsence(tenant.actors.admin, replacement)).toEqual(replacement);
    at(end);
    expect(await memberService.getAbsence(tenant.actors.member, input.orgId, input.userId)).toBeNull();
    await memberService.clearAbsence(tenant.actors.member, input.orgId, input.userId);
    await memberService.clearAbsence(tenant.actors.member, input.orgId, input.userId);
    expect(await absenceRepo.findAbsence(input.orgId, input.userId)).toBeNull();
  });

  it(\"checks scope, permissions, membership, delegates and interval validity\", async () => {
    const tenant = await createTenant(\"absence-validation\");
    const other = await createTenant(\"absence-other\");
    const input = absence(tenant);
    await expect(memberService.setAbsence(tenant.actors.viewer, input)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(memberService.clearAbsence(tenant.actors.viewer, input.orgId, input.userId)).rejects.toBeInstanceOf(PermissionDeniedError);
    for (const operation of [
      memberService.setAbsence(other.actors.owner, input),
      memberService.getAbsence(other.actors.owner, input.orgId, input.userId),
      memberService.clearAbsence(other.actors.owner, input.orgId, input.userId),
    ]) await expect(operation).rejects.toBeInstanceOf(TenantScopeError);
    await expect(memberService.setAbsence(tenant.actors.member, { ...input, endsAt: start })).rejects.toThrow();
    await expect(memberService.setAbsence(tenant.actors.member, { ...input, delegateUserId: input.userId })).rejects.toThrow();
    await expect(memberService.setAbsence(tenant.actors.member, { ...input, delegateUserId: other.userIds.member })).rejects.toBeInstanceOf(NotFoundError);
    await expect(memberService.getAbsence(tenant.actors.owner, input.orgId, other.userIds.member)).rejects.toBeInstanceOf(NotFoundError);
  });

  it(\"redirects stored assignments and their events and alerts, without chaining or overriding self-assignment\", async () => {
    const tenant = await createTenant(\"absence-assign\");
    await memberService.setAbsence(tenant.actors.member, absence(tenant));
    await memberService.setAbsence(tenant.actors.viewer, { ...absence(tenant), userId: tenant.userIds.viewer, delegateUserId: tenant.userIds.admin });
    at(start);
    const issue = await issueService.createIssue(tenant.actors.admin, issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }));
    expect(issue.assigneeId).toBe(tenant.userIds.viewer);
    expect(await alerts(tenant, \"member\", \"issue_assigned\")).toHaveLength(0);
    expect(await alerts(tenant, \"viewer\", \"issue_assigned\")).toHaveLength(1);
    const events: unknown[] = [];
    const off = subscribe(\"issue.assigned\", payload => { events.push(payload); });
    try {
      const assigned = await issueService.assignIssue(tenant.actors.admin, { orgId: tenant.org.id, issueId: issue.id, assigneeId: tenant.userIds.member });
      expect(assigned.assigneeId).toBe(tenant.userIds.viewer);
      expect(events[0]).toMatchObject({ assigneeId: tenant.userIds.viewer });
    } finally { off(); }
    const self = await issueService.assignIssue(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, assigneeId: tenant.userIds.member });
    expect(self.assigneeId).toBe(tenant.userIds.member);
    const selfCreated = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }));
    expect(selfCreated.assigneeId).toBe(tenant.userIds.member);
    at(end);
    const after = await issueService.createIssue(tenant.actors.admin, issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }));
    expect(after.assigneeId).toBe(tenant.userIds.member);
  });

  it(\"uses the event instant for overdue alerts and deduplicates mention delegates with their own preferences\", async () => {
    const tenant = await createTenant(\"absence-alerts\");
    const issue = await issueService.createIssue(tenant.actors.admin, issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }));
    await memberService.setAbsence(tenant.actors.member, absence(tenant));
    await preferenceRepo.upsertPreference({ orgId: tenant.org.id, userId: tenant.userIds.viewer, kind: \"comment_mention\", inApp: true, email: false, digestOnly: false });
    at(end);
    await emit(\"issue.overdue\", { orgId: tenant.org.id, actorId: null, occurredAt: start, issueId: issue.id, projectId: issue.projectId, dueAt: start, assigneeId: issue.assigneeId });
    expect(await alerts(tenant, \"member\", \"issue_overdue\")).toHaveLength(0);
    expect(await alerts(tenant, \"viewer\", \"issue_overdue\")).toHaveLength(1);
    await emit(\"comment.created\", { orgId: tenant.org.id, actorId: tenant.userIds.admin, occurredAt: start, commentId: \"absence-comment\" as CommentId, issueId: issue.id, mentionedUserIds: [tenant.userIds.member, tenant.userIds.viewer] });
    expect(await alerts(tenant, \"member\", \"comment_mention\")).toHaveLength(1);
    const delegateAlerts = await alerts(tenant, \"viewer\", \"comment_mention\");
    expect(delegateAlerts).toHaveLength(1);
    expect(delegateAlerts[0].channels).toEqual([\"in_app\"]);
    await emit(\"comment.created\", { orgId: tenant.org.id, actorId: tenant.userIds.viewer, occurredAt: start, commentId: \"absence-comment-2\" as CommentId, issueId: issue.id, mentionedUserIds: [tenant.userIds.member] });
    expect(await alerts(tenant, \"viewer\", \"comment_mention\")).toHaveLength(1);
    expect(await alerts(tenant, \"member\", \"comment_mention\")).toHaveLength(2);
  });

  it(\"removes absences with members and drops delegations to removed members\", async () => {
    const tenant = await createTenant(\"absence-removal\");
    await memberService.setAbsence(tenant.actors.member, absence(tenant));
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberService.removeMember(tenant.actors.admin, { orgId: tenant.org.id, memberId: viewer"'!.id });
    expect(await absenceRepo.findAbsence(tenant.org.id, tenant.userIds.member)).toMatchObject({ delegateUserId: null });
    await expect(memberService.setAbsence(tenant.actors.member, absence(tenant))).rejects.toBeInstanceOf(NotFoundError);
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberService.removeMember(tenant.actors.admin, { orgId: tenant.org.id, memberId: member!.id });
    expect(await absenceRepo.findAbsence(tenant.org.id, tenant.userIds.member)).toBeNull();
    await expect(memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member)).rejects.toBeInstanceOf(NotFoundError);
  });
});
EOF
